"Enter medicine / pharmacy item": "மருந்து / ஃபார்மசி பொருளை உள்ளிடவும்",
"Enter observations": "கவனித்தவற்றை உள்ளிடவும்",
"Enter resident name": "கெஸ்ட் பெயரை உள்ளிடவும்",
"Enter review remarks:": "பரிசீலனை குறிப்பை உள்ளிடவும்:",
"Enter task": "வேலையை உள்ளிடவும்",
"Enter the actual meal consumption time. The current time is not filled automatically.": "உண்மையில் சாப்பிட்ட நேரத்தை உள்ளிடவும். தற்போதைய நேரம் தானாக நிரப்பப்படாது.",
"Enter the actual return date and time, no later than now.": "உண்மையில் திரும்பிய தேதி மற்றும் நேரத்தை உள்ளிடவும் (இப்போதைக்கு பிறகு அல்ல).",
"Enter the hospital name for emergency transfer.": "அவசர மாற்றத்திற்கான மருத்துவமனை பெயரை உள்ளிடவும்.",
"Enter the reason for temporary delegation.": "தற்காலிக ஒப்படைப்பு காரணத்தை உள்ளிடவும்.",
"Enter the revised duty details or approval note:": "மாற்றிய டியூட்டி விவரம் அல்லது அனுமதி குறிப்பை உள்ளிடவும்:",
"Enter the visit date.": "வருகை தேதியை உள்ளிடவும்.",
"Enter what was done before marking it handled.": "கையாண்டதாக குறிக்கும் முன் என்ன செய்யப்பட்டது என உள்ளிடவும்.",
"Enter which juice was given (for example Orange, Mosambi, Pomegranate).": "எந்த ஜூஸ் கொடுத்தீர்கள் என உள்ளிடவும் (உதா: ஆரஞ்சு, சாத்துக்குடி, மாதுளை).",
"Enter your current password to change the Login ID.": "லாகின் ID மாற்ற உங்கள் தற்போதைய பாஸ்வேர்டை உள்ளிடவும்.",
"Enter your instruction / decision": "உங்கள் அறிவுறுத்தல் / முடிவை உள்ளிடவும்",
"Enter zero or a valid positive reorder level.": "பூஜ்யம் அல்லது சரியான மறு ஆர்டர் அளவை உள்ளிடவும்.",
"Every Movement": "ஒவ்வொரு நகர்வும்",
"Every charge request has been attended by Accounts within 30 minutes.": "ஒவ்வொரு கட்டண கோரிக்கையும் 30 நிமிடத்திற்குள் கணக்கு பார்த்துவிட்டது.",
"Every item needs a name (or remove the empty row).": "ஒவ்வொரு பொருளுக்கும் பெயர் தேவை (அல்லது காலி வரியை நீக்கவும்).",
"Every new enquiry (Website, WhatsApp, Walk-in, Phone) is assigned to this person and reminders go to them.": "ஒவ்வொரு புதிய என்கொயரியும் (வெப்சைட், WhatsApp, நேரில், ஃபோன்) இவருக்கு ஒதுக்கப்படும்; நினைவூட்டல்களும் இவருக்கே செல்லும்.",
"Every pharmacy or Stores item received from a vendor must first be entered here before issue.": "வெண்டரிடமிருந்து பெறும் ஒவ்வொரு ஃபார்மசி / ஸ்டோர்ஸ் பொருளும் வழங்கும் முன் இங்கே பதிவு செய்யப்பட வேண்டும்.",
"Every stock movement in the selected period and item, with the balance after each movement.": "தேர்ந்தெடுத்த காலம் மற்றும் பொருளின் ஒவ்வொரு ஸ்டாக் நகர்வும், ஒவ்வொன்றுக்கும் பிறகான மீதத்துடன்.",
"Example: 10 tablets": "உதா: 10 மாத்திரைகள்",
"Example: 2 days approved due to staffing requirement": "உதா: ஊழியர் தேவையால் 2 நாட்கள் அனுமதிக்கப்பட்டது",
"Example: Attend hospital inauguration": "உதா: மருத்துவமனை திறப்பு விழாவில் கலந்துகொள்",
"Example: Buy office printer": "உதா: ஆபீஸ் பிரிண்டர் வாங்கு",
"Example: Call Dr. ___ regarding referral": "உதா: பரிந்துரை பற்றி டாக்டர் ___ அழைக்கவும்",
