"Stock issued to a floor, the kitchen / pantry or another department (not charged to a resident). The stock balance reduces at once and the issue is recorded in the Stock Movement Register.": "தளம், கிச்சன் / பேன்ட்ரி அல்லது வேறு துறைக்கு வழங்கும் ஸ்டாக் (கெஸ்டுக்கு கட்டணம் இல்லை). ஸ்டாக் மீதம் உடனே குறையும்; ஸ்டாக் நகர்வு ரெஜிஸ்டரில் பதிவாகும்.",
