"Tap Speak, talk naturally, then tap Stop. Tamil/English will be converted and the form will be filled.": "\"பேசு\" தட்டி இயல்பாக பேசி, பிறகு \"நிறுத்து\" தட்டவும். தமிழ்/ஆங்கிலம் மாற்றப்பட்டு படிவம் நிரப்பப்படும்.",
