"Future physiotherapy session dates are not permitted.": "எதிர்காலத் தேதிக்கு பிசியோதெரபி பதிவு செய்ய முடியாது.",
"Not Done": "செய்யவில்லை",
"Unable to save physiotherapy session.": "பிசியோதெரபி அமர்வைச் சேமிக்க முடியவில்லை.",
"Record Session": "அமர்வைப் பதிவு செய்",
"Physiotherapy Plan": "பிசியோதெரபி திட்டம்",
"Therapy advised at discharge or during patient review": "டிஸ்சார்ஜ் அல்லது பார்வையின் போது பரிந்துரைக்கப்பட்ட சிகிச்சை",
