"Reason / Notes": "காரணம் / குறிப்பு",
"Record Physiotherapy Session": "பிசியோதெரபி அமர்வைப் பதிவு செய்",
"Reason (mandatory)": "காரணம் (கட்டாயம்)",
"Example: Patient refused / medically unfit / therapist unavailable": "உதாரணம்: கெஸ்ட் மறுத்தார் / உடல்நிலை சரியில்லை / தெரபிஸ்ட் வரவில்லை",
"Session Notes": "அமர்வுக் குறிப்புகள்",
"Exercises completed, patient tolerance, pain, mobility response or instructions": "செய்த பயிற்சிகள், தாங்கும் திறன், வலி, நகர்வு அல்லது அறிவுறுத்தல்கள்",
