"Session saved": "அமர்வு சேமிக்கப்பட்டது",
"Our Employee": "நம் பணியாளர்",
"Unable to load Special Nurse assignments.": "ஸ்பெஷல் நர்ஸ் நியமனங்களை ஏற்ற முடியவில்லை.",
"Please select the assigned patient.": "கெஸ்ட்டைத் தேர்வு செய்யவும்.",
