"Only employees with the role Nurse or Caregiver can be assigned for Special Nurse duty.": "நர்ஸ் அல்லது கேர்கிவர் மட்டுமே ஸ்பெஷல் நர்ஸ் டியூட்டிக்கு நியமிக்கப்படலாம்.",
"Outsourced": "வெளி நிறுவனம்",
"Please enter the outsourced Special Nurse name.": "வெளி ஸ்பெஷல் நர்ஸ் பெயரை எழுதவும்.",
"Please enter the outsourcing company or organisation name.": "வெளி நிறுவனத்தின் பெயரை எழுதவும்.",
"Select at least one coverage day.": "குறைந்தது ஒரு நாளைத் தேர்வு செய்யவும்.",
"Future assignment start dates are not permitted.": "எதிர்காலத் தொடக்கத் தேதி அனுமதிக்கப்படாது.",
"End date cannot be earlier than the start date.": "முடிவுத் தேதி தொடக்கத் தேதிக்கு முன் இருக்கக் கூடாது.",
"Unable to save Special Nurse assignment.": "ஸ்பெஷல் நர்ஸ் நியமனத்தைச் சேமிக்க முடியவில்லை.",
"Special Nurse assignment updated successfully.": "ஸ்பெஷல் நர்ஸ் நியமனம் புதுப்பிக்கப்பட்டது.",
"Special Nurse assigned successfully.": "ஸ்பெஷல் நர்ஸ் நியமிக்கப்பட்டார்.",
