"Signed Admission Consent Form": "கையொப்பமிட்ட அட்மிஷன் ஒப்புதல் படிவம்",
"Please use JPG/JPEG, PNG, HEIC/HEIF, WEBP or PDF files.": "JPG/JPEG, PNG, HEIC/HEIF, WEBP அல்லது PDF கோப்புகளைப் பயன்படுத்தவும்.",
"Signed Admission Consent uploaded. Admission formalities are now complete.": "கையொப்பமிட்ட ஒப்புதல் படிவம் அப்லோட் ஆனது. அட்மிஷன் நடைமுறைகள் முடிந்தன.",
"Patient photo": "கெஸ்ட் புகைப்படம்",
