"Prescription": "மருந்துச் சீட்டு",
"Discharge / transfer summary": "டிஸ்சார்ஜ் / மாற்றச் சுருக்கம்",
"Report": "அறிக்கை",
"Upload File": "கோப்பை அப்லோட் செய்",
