"Patient Photograph": "கெஸ்ட் புகைப்படம்",
"Family Contact 2 must use a different mobile number from Family Contact 1.": "குடும்பத் தொடர்பு 2-க்கு வேறு மொபைல் எண் வேண்டும்.",
"Enter the authorised family member name for family communication.": "அனுமதி பெற்ற குடும்ப உறுப்பினர் பெயரை எழுதவும்.",
"Enter a valid family WhatsApp number.": "சரியான குடும்ப WhatsApp எண்ணை எழுதவும்.",
