"Wound dressing": "காய டிரெஸ்ஸிங்",
"Yes": "ஆம்",
"You were signed out after 30 minutes of inactivity for security.": "30 நிமிடம் செயலின்றி இருந்ததால் பாதுகாப்புக்காக வெளியேற்றப்பட்டீர்கள்.",
"Your Login ID and password are private. Changing them does not alter your Employee ID, designation, department or ERP role.": "உங்கள் லாகின் ID மற்றும் பாஸ்வேர்டு தனிப்பட்டவை. இவற்றை மாற்றினாலும் ஊழியர் ID, பதவி, துறை அல்லது ERP பணி மாறாது.",
"Your employee profile is not linked to this Login ID. Please contact the Administrator.": "உங்கள் ஊழியர் விவரம் இந்த லாகின் ID-யுடன் இணைக்கப்படவில்லை. அட்மினை தொடர்பு கொள்ளவும்.",
"Your regular duties return automatically afterwards.": "பிறகு உங்கள் வழக்கமான டியூட்டிகள் தானாக திரும்பும்.",
"Your request will follow the configured approval hierarchy": "உங்கள் கோரிக்கை அமைக்கப்பட்ட அனுமதி வரிசையில் செல்லும்",
"Your session has expired. Please sign in again.": "உங்கள் அமர்வு முடிந்தது. மீண்டும் லாகின் செய்யவும்.",
"Open Samara Care ERP": "சமாரா கேர் ERP திற",
"View Family Portal": "ஃபேமிலி போர்டலை பார்",
"View Family Portal website": "ஃபேமிலி போர்டல் வெப்சைட்டை பார்",
"Play video": "வீடியோ இயக்கு",
