"Other — type your own item": "மற்றவை — உங்கள் உணவு வகையை தட்டச்சு செய்யவும்",
"Approved template accepted by Meta. Free-text reply will become available after the customer replies.": "அனுமதித்த டெம்ப்ளேட்டை Meta ஏற்றுக்கொண்டது. வாடிக்கையாளர் பதில் அளித்த பிறகு சாதாரண பதில் அனுப்பலாம்.",
"Emergency WhatsApp accepted by Meta and recorded in ERP Inbox.": "அவசர WhatsApp-ஐ Meta ஏற்றுக்கொண்டது; ERP இன்பாக்ஸில் பதிவானது.",
"Food & Diet settings saved successfully.": "உணவு & டயட் அமைப்புகள் சேமிக்கப்பட்டன.",
"Message deleted from the inbox. Admin can restore it from \"Show deleted\".": "செய்தி இன்பாக்ஸிலிருந்து நீக்கப்பட்டது. அட்மின் \"நீக்கியதை காட்டு\"-வில் மீட்டெடுக்கலாம்.",
"Message restored.": "செய்தி மீட்டெடுக்கப்பட்டது.",
"Password changed successfully. Your current session remains active.": "பாஸ்வேர்டு மாற்றப்பட்டது. உங்கள் தற்போதைய அமர்வு தொடரும்.",
"Personal contact details updated successfully.": "தனிப்பட்ட தொடர்பு விவரங்கள் புதுப்பிக்கப்பட்டன.",
"Responsibility assigned successfully.": "பொறுப்பு ஒதுக்கப்பட்டது.",
"Responsibility revoked successfully.": "பொறுப்பு திரும்பப் பெறப்பட்டது.",
"Saved successfully.": "வெற்றிகரமாக சேமிக்கப்பட்டது.",
"Use This Text": "இந்த உரையை பயன்படுத்து",
"Voice entry filled in simple English. Please check the fields before Save.": "குரல் பதிவு எளிய ஆங்கிலத்தில் நிரப்பப்பட்டது. சேமிக்கும் முன் சரிபார்க்கவும்.",
"WhatsApp attachment opened.": "WhatsApp இணைப்பு திறக்கப்பட்டது.",
"WhatsApp reply accepted by Meta. Message box cleared.": "WhatsApp பதிலை Meta ஏற்றுக்கொண்டது. செய்திப் பெட்டி காலியானது.",
"Close Receive from Vendor": "வெண்டரிடமிருந்து பெறுதலை மூடு",
