"Listening in English… Tap Stop when finished.": "ஆங்கிலத்தில் கேட்கிறது… முடிந்ததும் நிறுத்து தட்டவும்.",
"Listening in Tamil…": "தமிழில் கேட்கிறது…",
"Listening in Tamil… Tap Stop when finished.": "தமிழில் கேட்கிறது… முடிந்ததும் நிறுத்து தட்டவும்.",
"Speak naturally in English…": "ஆங்கிலத்தில் இயல்பாக பேசவும்…",
